(()=>{"use strict";(()=>{const e=document.querySelector("#timer-days"),t=document.querySelector("#timer-hours"),n=document.querySelector("#timer-minutes"),o=document.querySelector("#timer-seconds"),r=()=>{let e=(new Date("20 february 2025").getTime()-(new Date).getTime())/1e3;return{timeRemaning:e,days:Math.floor(e/60/60/24),hours:Math.floor(e/60/60%24),minutes:Math.floor(e/60%60),seconds:Math.floor(e%60)}},s=e=>e.toString().padStart(2,"0");r().timeRemaning>0&&setInterval((()=>{let m=r();e.textContent=s(m.days),t.textContent=s(m.hours),n.textContent=s(m.minutes),o.textContent=s(m.seconds)}),1e3)})()})();